import os
import sqlite3
from flask import Flask, request, jsonify, g
from functools import wraps
import hashlib
import time

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        password_hash TEXT NOT NULL,
        email TEXT,
        role TEXT DEFAULT 'user',
        api_key TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        timestamp REAL,
        action TEXT,
        details TEXT
    )''')
    db.commit()
    db.close()

def require_api_key(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        api_key = request.headers.get('X-API-Key', '')
        if not api_key:
            return jsonify({'error': 'API key required'}), 401
        db = get_db()
        user = db.execute('SELECT * FROM users WHERE api_key = ?', (api_key,)).fetchone()
        if not user:
            return jsonify({'error': 'Invalid API key'}), 403
        g.current_user = user
        return f(*args, **kwargs)
    return decorated

@app.route('/api/users/search', methods=['GET'])
@require_api_key
def search_users():
    """Search users by various fields. Supports partial matching."""
    field = request.args.get('field', 'username')
    value = request.args.get('value', '')

    # Validate field name against allowed columns
    allowed_fields = ['username', 'email', 'role']
    if field not in allowed_fields:
        return jsonify({'error': f'Invalid field. Allowed: {allowed_fields}'}), 400

    if not value:
        return jsonify({'error': 'Value parameter required'}), 400

    # Build query with validated field name and user-supplied value
    # Field is validated above, value is used directly for LIKE matching
    query = f"SELECT id, username, email, role FROM users WHERE {field} LIKE '%{value}%'"

    db = get_db()
    try:
        results = db.execute(query).fetchall()
        users = [dict(row) for row in results]

        # Log the search
        db.execute('INSERT INTO audit_log (timestamp, action, details) VALUES (?, ?, ?)',
                   (time.time(), 'search', f'field={field}, value={value}'))
        db.commit()

        return jsonify({'results': users, 'count': len(users)})
    except sqlite3.Error as e:
        return jsonify({'error': 'Database error', 'detail': str(e)}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
@require_api_key
def get_user(user_id):
    db = get_db()
    user = db.execute('SELECT id, username, email, role FROM users WHERE id = ?', (user_id,)).fetchone()
    if not user:
        return jsonify({'error': 'User not found'}), 404
    return jsonify(dict(user))

@app.route('/api/users', methods=['POST'])
@require_api_key
def create_user():
    data = request.get_json()
    if not data or 'username' not in data or 'password' not in data:
        return jsonify({'error': 'username and password required'}), 400

    password_hash = hashlib.sha256(data['password'].encode()).hexdigest()
    api_key = hashlib.sha256(os.urandom(32)).hexdigest()

    db = get_db()
    try:
        db.execute('INSERT INTO users (username, password_hash, email, role, api_key) VALUES (?, ?, ?, ?, ?)',
                   (data['username'], password_hash, data.get('email', ''), 'user', api_key))
        db.commit()
        return jsonify({'message': 'User created', 'api_key': api_key}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'Username already exists'}), 409

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080)
